<?php
/** Unified Role App Items source of truth. */
require_once __DIR__ . '/../../lib/Db.php';
require_once __DIR__ . '/../../lib/Jwt.php';
require_once __DIR__ . '/../../lib/Http.php';
$CONFIG=require __DIR__.'/../../config.php';
header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
function kh_auth_user(){global $CONFIG;$token=Http::bearer();$payload=$token?Jwt::verify($token,$CONFIG['jwt_secret']):null;if(!$payload||empty($payload['sub']))Http::error('توکن منقضی یا نامعتبر است',401);Http::$currentToken=$token;$user=Db::one("SELECT u.id,u.username,u.first_name,u.last_name,u.role_id,r.title AS role_title,r.level,r.is_admin,u.is_active,u.email,u.photo,u.photo_path FROM users u LEFT JOIN roles r ON r.id=u.role_id WHERE u.id=? LIMIT 1",[$payload['sub']]);if(!$user||!(int)$user['is_active'])Http::error('کاربر نامعتبر',401);$dt=$payload['dt']??'web';if(kh_table_exists('user_sessions')){$sess=Db::one("SELECT device_id,revoked_at FROM user_sessions WHERE user_id=? AND device_type=? ORDER BY id DESC LIMIT 1",[$user['id'],$dt]);$unlimited=in_array((string)$user['role_title'],['مدیر کل','رییس اداره بازرسی','نیروی اداری ارشد','admin','superadmin'],true)||!empty($user['is_admin']);if(!$sess||$sess['revoked_at']||(!$unlimited&&(string)$sess['device_id']!==(string)($payload['device_id']??'')))Http::error('نشست منقضی یا باطل شده است',401);}$user['device_id']=$payload['device_id']??null;$user['device_type']=$dt;return $user;}
function kh_table_exists($table){static $cache=[];if(isset($cache[$table]))return $cache[$table];try{$r=Db::one("SELECT COUNT(*) c FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?",[$table]);return $cache[$table]=((int)($r['c']??0)>0);}catch(Throwable $e){return $cache[$table]=false;}}
function kh_is_admin($u){return !empty($u['is_admin'])||in_array((string)($u['role_title']??''),['مدیر کل','رییس اداره بازرسی','نیروی اداری ارشد','admin','superadmin'],true);}
const KH_STATION_CAPTURE='StationCapture';const KH_MY_STATIONS='MyStations';const KH_LINE_LOCATION='LineLocation';
/* Canonical catalog: all existing items are retained; LineLocation is "نمایش موقعیت هر خط". */
$allItems=['Search','PresentList','Reports','CheckIn','Requests','RequestInbox','WorkSummary','SalarySlips','CompanyRequests','Subscription','Sms','BotMessages','MySms','Forms','Cultural','Welfare','OfficialPresence','Inventory','MyDailyMission','LineVisitProgram',KH_LINE_LOCATION,KH_STATION_CAPTURE,KH_MY_STATIONS,'RoleDashboard','Leaderboard','ActivityReport','ExpInsurance','ExpTaxi','ExpOplic','TeamReport','TempDrivers','Outage'];
function kh_read_config($pdo){try{$row=$pdo->query("SELECT value FROM app_settings WHERE `key`='role_app_items' LIMIT 1")->fetch(PDO::FETCH_ASSOC);if(!$row)return [];$cfg=json_decode((string)$row['value'],true);return is_array($cfg)?$cfg:[];}catch(Throwable $e){error_log('unified-role-app-items config: '.$e->getMessage());return [];}}
function kh_roles($pdo){$roles=[];try{$rows=$pdo->query("SELECT id,title FROM roles ORDER BY id")->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $r)$roles[]=['id'=>(string)$r['id'],'title'=>(string)$r['title'];}catch(Throwable $e){error_log('unified-role-app-items roles: '.$e->getMessage());}return $roles;}
function kh_clean_items($items){if(!is_array($items))return []; $seen=[];$out=[];foreach($items as $x){$x=(string)$x;if($x===''||isset($seen[$x]))continue;$seen[$x]=true;$out[]=$x;}return $out;}
function kh_normalize_config($cfg,$roles,$allItems){$out=[];foreach($roles as $r){$rid=(string)$r['id'];if(!array_key_exists($rid,$cfg))continue;$v=$cfg[$rid];$out[$rid]=is_array($v)?kh_clean_items($v):$allItems;}return $out;}
try{$user=kh_auth_user();$pdo=Db::pdo();$method=$_SERVER['REQUEST_METHOD']??'GET';$cfg=kh_read_config($pdo);$roles=kh_roles($pdo);if($method==='GET'){if(kh_is_admin($user)){echo json_encode(['success'=>true,'roles'=>$roles,'config'=>$cfg,'items'=>$allItems,'default_items'=>$allItems,'source'=>'role_app_items'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}$rid=(string)($user['role_id']??'');$items=(!array_key_exists($rid,$cfg)||!is_array($cfg[$rid]))?$allItems:kh_clean_items($cfg[$rid]);echo json_encode(['success'=>true,'items'=>$items,'source'=>'role_app_items'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}if($method==='POST'){if(!kh_is_admin($user))Http::error('دسترسی غیرمجاز',403);$in=Http::body();$newCfg=$in['config']??null;if(!is_array($newCfg))Http::error('تنظیمات آیتم‌های اپ نامعتبر است',422);$newCfg=kh_normalize_config($newCfg,$roles,$allItems);$js=json_encode($newCfg,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$st=$pdo->prepare("INSERT INTO app_settings(`key`,`value`) VALUES('role_app_items',?) ON DUPLICATE KEY UPDATE `value`=VALUES(`value`)");$st->execute([$js]);echo json_encode(['success'=>true,'ok'=>true,'config'=>$newCfg,'items'=>$allItems,'roles'=>$roles,'default_items'=>$allItems,'source'=>'role_app_items'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}Http::error('Method not allowed',405);}catch(Throwable $e){error_log('unified-role-app-items fatal: '.$e->getMessage());http_response_code(500);echo json_encode(['success'=>false,'error'=>'خطای داخلی در بارگذاری تنظیمات سمت‌ها و آیتم‌های اپ'],JSON_UNESCAPED_UNICODE);}
